
let pdfiumInitialized = false;

function getPdfium() {
    let p = null;
    if (typeof globalThis !== 'undefined') {
        if (globalThis.__pdfium && globalThis.__pdfium._FPDF_LoadMemDocument) {
            p = globalThis.__pdfium;
        } else if (globalThis.Module && globalThis.Module._FPDF_LoadMemDocument) {
            p = globalThis.Module;
        }
    }
    if (p && !pdfiumInitialized) {
        if (typeof p._FPDF_InitLibrary === 'function') {
            try {
                p._FPDF_InitLibrary();
            } catch (_) {}
        }
        pdfiumInitialized = true;
    }
    return p;
}

function yToTopLeft(pageHeight, top) {
    return pageHeight >= top ? pageHeight - top : top;
}

export function pdfium_is_available() {
    return getPdfium() !== null;
}

export function pdfium_open_doc(bytes, password) {
    const p = getPdfium();
    if (!p) {
        throw new Error("PDFium WASM engine is not initialized. Please ensure pdfium.js is loaded in the browser.");
    }
    const len = bytes.length;
    const ptr = p._malloc(len);
    p.HEAPU8.set(bytes, ptr);
    
    let passPtr = 0;
    if (password && password.length > 0) {
        const passBytes = new TextEncoder().encode(password + '\0');
        passPtr = p._malloc(passBytes.length);
        p.HEAPU8.set(passBytes, passPtr);
    }
    
    const doc = p._FPDF_LoadMemDocument(ptr, len, passPtr);
    if (passPtr) p._free(passPtr);
    
    if (!doc) {
        p._free(ptr);
        const err = p._FPDF_GetLastError();
        throw new Error("Failed to parse PDF bytes: PDFium error " + err);
    }
    return [doc, ptr];
}

export function pdfium_close_doc(doc, ptr) {
    const p = getPdfium();
    if (!p) return;
    if (doc) p._FPDF_CloseDocument(doc);
    if (ptr) p._free(ptr);
}

export function pdfium_get_page_count(doc) {
    const p = getPdfium();
    return (p && doc) ? p._FPDF_GetPageCount(doc) : 0;
}

export function pdfium_load_page(doc, pageIndex) {
    const p = getPdfium();
    if (!p || !doc) return 0;
    return p._FPDF_LoadPage(doc, pageIndex);
}

export function pdfium_close_page(page) {
    const p = getPdfium();
    if (p && page) p._FPDF_ClosePage(page);
}

export function pdfium_get_page_size(page) {
    const p = getPdfium();
    if (!p || !page) return [0, 0];
    const w = p._FPDF_GetPageWidth(page);
    const h = p._FPDF_GetPageHeight(page);
    return [w, h];
}

export function pdfium_extract_chars(page) {
    const p = getPdfium();
    if (!p || !page) return [];
    const textPage = p._FPDFText_LoadPage(page);
    if (!textPage) return [];
    
    const count = p._FPDFText_CountChars(textPage);
    const result = [];
    
    const rawPtr = p._malloc(320);
    const aligned = (rawPtr + 7) & ~7;
    const leftPtr = aligned;
    const rightPtr = aligned + 8;
    const bottomPtr = aligned + 16;
    const topPtr = aligned + 24;
    const fontBufPtr = aligned + 32;
    const flagsPtr = aligned + 288;
    
    const pageHeight = p._FPDF_GetPageHeight(page);
    const decoder = typeof TextDecoder !== 'undefined' ? new TextDecoder() : null;
    
    for (let i = 0; i < count; i++) {
        const cp = p._FPDFText_GetUnicode(textPage, i);
        if (cp === 0) continue;
        const ch = String.fromCodePoint(cp);
        const ok = p._FPDFText_GetCharBox(textPage, i, leftPtr, rightPtr, bottomPtr, topPtr);
        if (ok) {
            const left = p.HEAPF64[leftPtr >> 3];
            const right = p.HEAPF64[rightPtr >> 3];
            const bottom = p.HEAPF64[bottomPtr >> 3];
            const top = p.HEAPF64[topPtr >> 3];
            const w = Math.abs(right - left);
            const h = Math.abs(top - bottom);
            const y = yToTopLeft(pageHeight, top);

            const fontSize = p._FPDFText_GetFontSize ? p._FPDFText_GetFontSize(textPage, i) : 0.0;
            let fontWeight = p._FPDFText_GetFontWeight ? p._FPDFText_GetFontWeight(textPage, i) : 400;

            let fontFamily = "";
            if (p._FPDFText_GetFontInfo) {
                const fontLen = p._FPDFText_GetFontInfo(textPage, i, fontBufPtr, 256, flagsPtr);
                if (fontLen > 0) {
                    let end = fontBufPtr;
                    while (p.HEAPU8[end] !== 0 && (end - fontBufPtr) < fontLen) {
                        end++;
                    }
                    if (decoder) {
                        fontFamily = decoder.decode(p.HEAPU8.subarray(fontBufPtr, end));
                    }
                }
            }
            if (fontWeight <= 0) {
                const flags = p.HEAP32[flagsPtr >> 2];
                fontWeight = (flags & 0x00040000) ? 700 : 400;
            }

            result.push({
                character: ch,
                bbox: { x: left, y: y, width: w, height: h },
                font_size: fontSize,
                font_weight: fontWeight,
                font_family: fontFamily
            });
        }
    }
    
    p._free(rawPtr);
    p._FPDFText_ClosePage(textPage);
    return result;
}

export function pdfium_extract_paths(page) {
    const p = getPdfium();
    if (!p || !page) return [];
    const count = p._FPDFPage_CountObjects(page);
    const paths = [];
    const pageHeight = p._FPDF_GetPageHeight(page);
    
    const sp = p.stackSave ? p.stackSave() : 0;
    const ptr = p.stackAlloc ? p.stackAlloc(48) : p._malloc(48);
    const lPtr = ptr;
    const bPtr = ptr + 4;
    const rPtr = ptr + 8;
    const tPtr = ptr + 12;
    const strokeWPtr = ptr + 16;
    const fillModePtr = ptr + 20;
    const strokeBoolPtr = ptr + 24;
    const colorRPtr = ptr + 28;
    const colorGPtr = ptr + 32;
    const colorBPtr = ptr + 36;
    const colorAPtr = ptr + 40;
    
    for (let i = 0; i < count; i++) {
        const obj = p._FPDFPage_GetObject(page, i);
        if (!obj) continue;
        const type = p._FPDFPageObj_GetType(obj);
        if (type !== 2) continue; // FPDF_PAGEOBJ_PATH
        
        if (p._FPDFPageObj_GetBounds(obj, lPtr, bPtr, rPtr, tPtr)) {
            const left = p.HEAPF32[lPtr >> 2];
            const bottom = p.HEAPF32[bPtr >> 2];
            const right = p.HEAPF32[rPtr >> 2];
            const top = p.HEAPF32[tPtr >> 2];
            const w = Math.abs(right - left);
            const h = Math.abs(top - bottom);
            const y = yToTopLeft(pageHeight, top);
            
            let strokeWidth = 1.0;
            if (p._FPDFPageObj_GetStrokeWidth(obj, strokeWPtr)) {
                strokeWidth = p.HEAPF32[strokeWPtr >> 2];
            }
            
            let hasFill = false;
            let hasStroke = false;
            if (p._FPDFPath_GetDrawMode(obj, fillModePtr, strokeBoolPtr)) {
                hasFill = p.HEAP32[fillModePtr >> 2] !== 0;
                hasStroke = p.HEAP32[strokeBoolPtr >> 2] !== 0;
            }

            let strokeColor = null;
            if (hasStroke && p._FPDFPageObj_GetStrokeColor && p._FPDFPageObj_GetStrokeColor(obj, colorRPtr, colorGPtr, colorBPtr, colorAPtr)) {
                strokeColor = {
                    r: p.HEAPU32[colorRPtr >> 2],
                    g: p.HEAPU32[colorGPtr >> 2],
                    b: p.HEAPU32[colorBPtr >> 2],
                    a: p.HEAPU32[colorAPtr >> 2]
                };
            }

            let fillColor = null;
            if (hasFill && p._FPDFPageObj_GetFillColor && p._FPDFPageObj_GetFillColor(obj, colorRPtr, colorGPtr, colorBPtr, colorAPtr)) {
                fillColor = {
                    r: p.HEAPU32[colorRPtr >> 2],
                    g: p.HEAPU32[colorGPtr >> 2],
                    b: p.HEAPU32[colorBPtr >> 2],
                    a: p.HEAPU32[colorAPtr >> 2]
                };
            }
            
            const segCount = p._FPDFPath_CountSegments(obj);
            let isClosed = false;
            if (segCount > 0) {
                const lastSeg = p._FPDFPath_GetPathSegment(obj, segCount - 1);
                if (lastSeg && p._FPDFPathSegment_GetClose(lastSeg)) {
                    isClosed = true;
                }
            }
            
            paths.push({
                bbox: { x: left, y: y, width: w, height: h },
                stroke_width: strokeWidth,
                stroke_color: strokeColor,
                fill_color: fillColor,
                has_stroke: hasStroke,
                has_fill: hasFill,
                is_closed: isClosed
            });
        }
    }
    
    if (p.stackRestore && sp) p.stackRestore(sp);
    else if (!p.stackAlloc) p._free(ptr);
    return paths;
}

export function pdfium_extract_images(page) {
    const p = getPdfium();
    if (!p || !page) return [];
    const count = p._FPDFPage_CountObjects(page);
    const images = [];
    const pageHeight = p._FPDF_GetPageHeight(page);
    
    const sp = p.stackSave ? p.stackSave() : 0;
    const ptr = p.stackAlloc ? p.stackAlloc(24) : p._malloc(24);
    const lPtr = ptr;
    const bPtr = ptr + 4;
    const rPtr = ptr + 8;
    const tPtr = ptr + 12;
    const wPtr = ptr + 16;
    const hPtr = ptr + 20;
    
    for (let i = 0; i < count; i++) {
        const obj = p._FPDFPage_GetObject(page, i);
        if (!obj) continue;
        const type = p._FPDFPageObj_GetType(obj);
        if (type !== 3) continue; // FPDF_PAGEOBJ_IMAGE
        
        if (p._FPDFPageObj_GetBounds(obj, lPtr, bPtr, rPtr, tPtr)) {
            const left = p.HEAPF32[lPtr >> 2];
            const bottom = p.HEAPF32[bPtr >> 2];
            const right = p.HEAPF32[rPtr >> 2];
            const top = p.HEAPF32[tPtr >> 2];
            const w = Math.abs(right - left);
            const h = Math.abs(top - bottom);
            const y = yToTopLeft(pageHeight, top);
            
            let pixelW = Math.round(w);
            let pixelH = Math.round(h);
            if (p._FPDFImageObj_GetImagePixelSize && p._FPDFImageObj_GetImagePixelSize(obj, wPtr, hPtr)) {
                pixelW = p.HEAP32[wPtr >> 2];
                pixelH = p.HEAP32[hPtr >> 2];
            }
            
            images.push({
                bbox: { x: left, y: y, width: w, height: h },
                pixel_width: pixelW,
                pixel_height: pixelH
            });
        }
    }
    
    if (p.stackRestore && sp) p.stackRestore(sp);
    else if (!p.stackAlloc) p._free(ptr);
    return images;
}

export function pdfium_render_page_bgra(page, targetWidth, targetHeight) {
    const p = getPdfium();
    if (!p || !page) return { bgra: new Uint8Array(0), stride: 0 };
    
    const bitmap = p._FPDFBitmap_Create(targetWidth, targetHeight, 0);
    if (!bitmap) return { bgra: new Uint8Array(0), stride: 0 };
    
    p._FPDFBitmap_FillRect(bitmap, 0, 0, targetWidth, targetHeight, 0xFFFFFFFF);
    p._FPDF_RenderPageBitmap(bitmap, page, 0, 0, targetWidth, targetHeight, 0, 0x801);
    
    const stride = p._FPDFBitmap_GetStride(bitmap);
    const bufPtr = p._FPDFBitmap_GetBuffer(bitmap);
    const totalBytes = stride * targetHeight;
    const bgra = new Uint8Array(p.HEAPU8.subarray(bufPtr, bufPtr + totalBytes));
    p._FPDFBitmap_Destroy(bitmap);
    
    return { bgra, stride };
}
