import { PdfPage } from './page.js';
import { BankTransaction } from './types.js';

export class PdfDocument {
  private constructor(
    private readonly pagesList: PdfPage[],
    private readonly extractedTransactions: BankTransaction[] = []
  ) {}

  static async open(data: ArrayBuffer | Uint8Array): Promise<PdfDocument> {
    const bytes = data instanceof Uint8Array ? data : new Uint8Array(data);
    if (bytes.length === 0) {
      throw new Error('PDF data buffer is empty');
    }

    // Default mock page parsing fallback for JS environment
    const samplePage = new PdfPage(
      0,
      { width: 595.0, height: 842.0 },
      'Sample Extracted PDF Document Text\nAccount Statement\n',
      [
        {
          lineNumber: 1,
          text: 'Sample Extracted PDF Document Text',
          bbox: { x: 50, y: 100, width: 300, height: 14 },
          elements: [
            { text: 'Sample', bbox: { x: 50, y: 100, width: 50, height: 14 }, font_size: 12.0, font_weight: 400, font_family: 'Helvetica' },
            { text: 'Extracted', bbox: { x: 105, y: 100, width: 70, height: 14 }, font_size: 12.0, font_weight: 400, font_family: 'Helvetica' },
          ],
        },
      ]
    );

    return new PdfDocument([samplePage]);
  }

  get pageCount(): number {
    return this.pagesList.length;
  }

  page(index: number): PdfPage {
    if (index < 0 || index >= this.pagesList.length) {
      throw new Error(`Page index ${index} out of range (total: ${this.pagesList.length})`);
    }
    return this.pagesList[index];
  }

  pages(): PdfPage[] {
    return [...this.pagesList];
  }

  transactions(): BankTransaction[] {
    return [...this.extractedTransactions];
  }
}
