import { ImageElement, PageDimensions, PathElement, TextLine } from './types.js';

export class PdfPage {
  constructor(
    public readonly index: number,
    public readonly dimensions: PageDimensions,
    private readonly rawText: string,
    private readonly linesList: TextLine[] = [],
    private readonly pathsList: PathElement[] = [],
    private readonly imagesList: ImageElement[] = []
  ) {}

  get width(): number {
    return this.dimensions.width;
  }

  get height(): number {
    return this.dimensions.height;
  }

  async text(): Promise<string> {
    return this.rawText;
  }

  async lines(): Promise<TextLine[]> {
    return this.linesList;
  }

  async paths(): Promise<PathElement[]> {
    return this.pathsList;
  }

  async images(): Promise<ImageElement[]> {
    return this.imagesList;
  }

  async horizontalLines(maxThickness = 2.0): Promise<PathElement[]> {
    return this.pathsList.filter(
      (p) => p.bbox.height <= maxThickness && p.bbox.width > p.bbox.height * 2.0
    );
  }

  async verticalLines(maxThickness = 2.0): Promise<PathElement[]> {
    return this.pathsList.filter(
      (p) => p.bbox.width <= maxThickness && p.bbox.height > p.bbox.width * 2.0
    );
  }
}
